    /// other protocols (e.g. `link:`) are skipped.
    fn add_injected_package(
        &self,
        name: &str,
        version: &str,
        pruned_packages: &mut Packages,
        pruned_snapshots: &mut Option<Snapshots>,
    ) {
        // Only `file:` resolutions have corresponding packages/snapshots entries.
        if !version.starts_with("file:") {
            return;
        }

        let package_key = self.format_key(name, version);

        if let Some(entry) = self.get_packages(&package_key) {
            pruned_packages.insert(package_key.clone(), entry.clone());
        }

        // Add the injected package's snapshot and traverse its direct
        // dependencies, adding each to both the packages and snapshots maps.
        if let Some(snapshot) = self
            .snapshots
            .as_ref()
            .and_then(|snapshots| snapshots.get(&package_key))
        {
            pruned_snapshots
                .get_or_insert_with(HashMap::new)
                .insert(package_key.clone(), snapshot.clone());

            for (dep_name, dep_version) in snapshot.dependencies() {
                let dep_key = self.format_key(&dep_name, &dep_version);

                if let Some(entry) = self.get_packages(&dep_key) {
                    pruned_packages.insert(dep_key.clone(), entry.clone());
                }

                if let Some(dep_snapshot) = self
                    .snapshots
                    .as_ref()
                    .and_then(|snapshots| snapshots.get(&dep_key))
                {
                    pruned_snapshots
                        .get_or_insert_with(HashMap::new)
                        .insert(dep_key, dep_snapshot.clone());
                }
            }
        }
    }

